package net.civeira.phylax.feature.notification.smtpoutboundconfig.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.SmtpOutboundConfig;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.event.SmtpOutboundConfigEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class SmtpOutboundConfigEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<SmtpOutboundConfigEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final SmtpOutboundConfig entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
